using System.Data;
using Essco.Application.Purchasing;
using Essco.Domain.Purchasing;
using Microsoft.Data.SqlClient;
namespace Essco.Infrastructure.Data;

public sealed class SqlServerPurchaseOrderRepository(string connectionString, int timeout) : IPurchaseOrderRepository
{
    public async ValueTask<IReadOnlyCollection<PurchaseOrder>> ListAsync(PurchaseOrderFilter f, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd("", c); var w = new List<string>(); if (f.Number is not null) { w.Add("[NumDoc]=@Number"); cmd.Parameters.Add("@Number", SqlDbType.Int).Value = f.Number; } if (!string.IsNullOrWhiteSpace(f.Supplier)) { w.Add("([CardCode]=@Supplier OR [NombreProveedor] LIKE @SupplierLike)"); cmd.Parameters.Add("@Supplier", SqlDbType.NVarChar, 50).Value = f.Supplier.Trim(); cmd.Parameters.Add("@SupplierLike", SqlDbType.NVarChar, 200).Value = $"%{f.Supplier.Trim()}%"; } if (f.From is not null) { w.Add("[Fecha]>=@From"); cmd.Parameters.Add("@From", SqlDbType.Date).Value = f.From.Value.ToDateTime(TimeOnly.MinValue); } if (f.To is not null) { w.Add("[Fecha]<DATEADD(day,1,@To)"); cmd.Parameters.Add("@To", SqlDbType.Date).Value = f.To.Value.ToDateTime(TimeOnly.MinValue); } if (f.CreatedInSap is not null) { w.Add("ISNULL([CreadoSAP],0)=@Sap"); cmd.Parameters.Add("@Sap", SqlDbType.Bit).Value = f.CreatedInSap; } cmd.CommandText = $"SELECT TOP(500) [NumDoc],MIN([Fecha]) [Fecha],MAX([CardCode]) [CardCode],MAX([NombreProveedor]) [NombreProveedor],MAX([Cerrado]) [Cerrado],MAX([CreadoSAP]) [CreadoSAP] FROM [dbo].[Pedidor]{(w.Count == 0 ? "" : " WHERE " + string.Join(" AND ", w))} GROUP BY [NumDoc] ORDER BY [NumDoc] DESC"; var a = new List<PurchaseOrder>(); await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) a.Add(Header(r, [])); return a; }
    public async ValueTask<PurchaseOrder?> GetAsync(int n, CancellationToken t) { await using var c = await Open(t); PurchaseOrder? h; await using (var cmd = Cmd("SELECT TOP(1) [NumDoc],[Fecha],[CardCode],[NombreProveedor],[Cerrado],[CreadoSAP] FROM [dbo].[Pedidor] WHERE [NumDoc]=@Number", c)) { cmd.Parameters.Add("@Number", SqlDbType.Int).Value = n; await using var r = await cmd.ExecuteReaderAsync(t); h = await r.ReadAsync(t) ? Header(r, []) : null; } if (h is null) return null; var lines = new List<PurchaseOrderLine>(); await using (var cmd = Cmd("SELECT [ID],[ItemCode],[ItemName],[Costo],[Pack],[Pd_Unid],[Pd_CJs],[Pd_Total],[Revizado],[Motivo] FROM [dbo].[Pedidor] WHERE [NumDoc]=@Number ORDER BY [ID]", c)) { cmd.Parameters.Add("@Number", SqlDbType.Int).Value = n; await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) lines.Add(new(Convert.ToInt64(r["ID"]), S(r, "ItemCode"), S(r, "ItemName"), D(r, "Costo"), D(r, "Pack"), D(r, "Pd_Unid"), D(r, "Pd_CJs"), D(r, "Pd_Total"), B(r, "Revizado"), S(r, "Motivo"))); } return h with { Lines = lines }; }
    public async ValueTask<bool> UpdateLineAsync(int n, PurchaseOrderLine l, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd("UPDATE [dbo].[Pedidor] SET [Pd_Total]=@Total,[Pd_CJs]=@Cases,[Pd_Unid]=@Units,[Revizado]=1,[Motivo]=@Reason WHERE [ID]=@Id AND [NumDoc]=@Number AND ISNULL([Cerrado],0)=0 AND ISNULL([CreadoSAP],0)=0", c); Dec(cmd, "@Total", l.Total); Dec(cmd, "@Cases", l.Cases); Dec(cmd, "@Units", l.Units); cmd.Parameters.Add("@Reason", SqlDbType.NVarChar, 500).Value = l.Reason.Trim(); cmd.Parameters.Add("@Id", SqlDbType.BigInt).Value = l.Id; cmd.Parameters.Add("@Number", SqlDbType.Int).Value = n; return await cmd.ExecuteNonQueryAsync(t) == 1; }
    public async ValueTask<bool> CancelAsync(int n, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd("UPDATE [dbo].[Pedidor] SET [Cerrado]=1 WHERE [NumDoc]=@Number AND ISNULL([CreadoSAP],0)=0", c); cmd.Parameters.Add("@Number", SqlDbType.Int).Value = n; return await cmd.ExecuteNonQueryAsync(t) > 0; }
    public async ValueTask<bool> MarkCreatedAsync(int n, int e, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd("UPDATE [dbo].[Pedidor] SET [CreadoSAP]=1,[Cerrado]=1 WHERE [NumDoc]=@Number AND ISNULL([CreadoSAP],0)=0", c); cmd.Parameters.Add("@Number", SqlDbType.Int).Value = n; return await cmd.ExecuteNonQueryAsync(t) > 0; }
    private static PurchaseOrder Header(SqlDataReader r, IReadOnlyCollection<PurchaseOrderLine> l) => new(Convert.ToInt32(r["NumDoc"]), DateOnly.FromDateTime(Convert.ToDateTime(r["Fecha"])), S(r, "CardCode"), S(r, "NombreProveedor"), B(r, "Cerrado"), B(r, "CreadoSAP"), l); private static string S(SqlDataReader r, string n) => Convert.ToString(r[n])?.Trim() ?? ""; private static decimal D(SqlDataReader r, string n) => r[n] is DBNull ? 0 : Convert.ToDecimal(r[n]); private static bool B(SqlDataReader r, string n) => r[n] is not DBNull && (r[n] is bool b ? b : Convert.ToString(r[n])?.Trim() is "1" or "True" or "TRUE" or "SI"); private async ValueTask<SqlConnection> Open(CancellationToken t) { var c = new SqlConnection(connectionString); await c.OpenAsync(t); return c; }
    private SqlCommand Cmd(string s, SqlConnection c) => new(s, c) { CommandTimeout = timeout }; private static void Dec(SqlCommand c, string n, decimal v) { var p = c.Parameters.Add(n, SqlDbType.Decimal); p.Precision = 19; p.Scale = 4; p.Value = v; }
}
